CREATE OR REPLACE FUNCTION public.cbt_can_manage(_user_id uuid DEFAULT auth.uid())
 RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
  SELECT (_user_id IS NOT NULL AND (
    public.has_permission(_user_id,'hrms_quiz_manage') OR public.has_permission(_user_id,'hrms_quiz_admin')
    OR public.has_permission(_user_id,'super_admin_access')))
  -- system content path: only inside a privileged migration session that sets the flag for its own transaction; never reachable through the API
  OR (_user_id IS NULL AND session_user NOT IN ('authenticator','anon','authenticated','service_role')
      AND COALESCE(current_setting('cbt.system_content', true), '') = 'on')
$function$;
SELECT set_config('cbt.system_content','on',true);
SELECT public.cbt_save_subject('written_communication','hiring','Written communication','General business writing: replies, explanations and summaries');
SELECT public.cbt_save_subject('typing_passages','shared','Typing passages','General English passages for typing sections');
DO $D$ DECLARE r jsonb; o jsonb; BEGIN
FOR r IN SELECT value FROM jsonb_array_elements($J$[["lo","e","Book is to library as painting is to...",["Gallery","Brush","Artist","Frame"],0,"Books are kept in a library; paintings are displayed in a gallery."],["lo","e","All roses are flowers. Some flowers fade quickly. Which statement must be true?",["Some roses fade quickly","Every rose is a flower","No rose fades quickly","All flowers are roses"],1,"Only that every rose is a flower follows; nothing says which flowers fade."],["lo","e","If yesterday was Friday, what day is tomorrow?",["Saturday","Monday","Sunday","Thursday"],2,"Yesterday Friday means today is Saturday, so tomorrow is Sunday."],["lo","e","Find the odd one out: Apple, Mango, Carrot, Banana",["Apple","Mango","Banana","Carrot"],3,"Carrot is a vegetable; the others are fruits."],["lo","e","Ravi is older than Sita. Sita is older than Arun. Who is the oldest?",["Ravi","Sita","Arun","Cannot be determined"],0,"Ravi > Sita > Arun."],["lo","e","Doctor is to hospital as teacher is to...",["Book","School","Student","Chalk"],1,"A doctor works in a hospital; a teacher works in a school."],["lo","m","In a code, CAT is written as DBU. How is DOG written?",["EOH","DPH","EPH","FPI"],2,"Each letter moves one place forward: D-E, O-P, G-H."],["lo","m","Some managers are engineers. All engineers are graduates. Which conclusion follows?",["All managers are graduates","No manager is a graduate","All graduates are engineers","Some managers are graduates"],3,"The managers who are engineers are also graduates."],["lo","m","A meeting is held every third day, starting on a Monday. On which day is the 4th meeting?",["Wednesday","Sunday","Thursday","Saturday"],0,"Meetings fall on Monday, Thursday, Sunday and then Wednesday."],["lo","m","Priya faces north, turns 90 degrees clockwise, then turns 180 degrees. Which direction does she face now?",["East","West","South","North"],1,"North to east, then a half turn from east is west."],["lo","m","If 'sky' is called 'sea', 'sea' is called 'road' and 'road' is called 'tree', on what do cars travel?",["Road","Sea","Tree","Sky"],2,"Cars travel on a road, and a road is called 'tree'."],["lo","m","Four friends sit in a row. Amit is right of Bina, Chetan is left of Bina, and Dev is right of Amit. Who is second from the left?",["Amit","Chetan","Dev","Bina"],3,"The order from the left is Chetan, Bina, Amit, Dev."],["lo","h","A is B's sister. C is B's mother. D is C's father. How is A related to D?",["Granddaughter","Daughter","Niece","Sister"],0,"A is a child of C, and C is D's child, so A is D's granddaughter."],["lo","h","In a code, MONDAY is written as NPOEBZ. How is FRIDAY written?",["GSJEBY","GSJEBZ","ESHCZX","GSKEBZ"],1,"Each letter moves one place forward."],["lo","h","No clerk is lazy. Some lazy people are rich. Which conclusion definitely follows?",["Some clerks are rich","No clerk is rich","Some rich people are not clerks","All rich people are lazy"],2,"The rich people who are lazy cannot be clerks."],["lo","h","Five boxes are stacked. P is above Q but below R. S is below Q. T is at the top. Which box is in the middle?",["Q","R","S","P"],3,"From the top: T, R, P, Q, S."],["lo","h","If the day after tomorrow is Saturday, what day was it three days before yesterday?",["Sunday","Monday","Saturday","Tuesday"],0,"Today is Thursday, yesterday Wednesday, three days before that is Sunday."],["lo","h","A clock gains 5 minutes every hour. It is set right at 6:00 am. What time does it show at 6:00 pm the same day?",["6:30 pm","7:00 pm","7:05 pm","6:55 pm"],1,"12 hours x 5 minutes = 60 minutes ahead."],["pa","e","3, 6, 9, 12, ?",["14","16","15","18"],2,"Add 3 each time."],["pa","e","50, 45, 40, 35, ?",["25","32","33","30"],3,"Subtract 5 each time."],["pa","e","B, D, F, H, ?",["J","I","K","L"],0,"Skip one letter each time."],["pa","e","1, 3, 5, 7, ?",["8","9","10","11"],1,"Odd numbers in order."],["pa","e","Red, Blue, Red, Blue, ?",["Blue","Green","Red","Yellow"],2,"The two colours alternate."],["pa","e","10, 20, 30, 40, ?",["45","60","55","50"],3,"Add 10 each time."],["pa","m","2, 5, 11, 23, ?",["47","46","45","49"],0,"Double and add 1."],["pa","m","1, 2, 6, 24, ?",["96","120","48","72"],1,"Multiply by 2, 3, 4, then 5."],["pa","m","A, D, G, J, ?",["L","N","M","K"],2,"Move three letters forward each time."],["pa","m","64, 32, 16, 8, ?",["2","6","0","4"],3,"Halve each time."],["pa","m","5, 9, 17, 33, ?",["65","64","49","66"],0,"The differences double: 4, 8, 16, 32."],["pa","m","AB, CD, EF, GH, ?",["HI","IJ","JK","IK"],1,"Consecutive letter pairs."],["pa","h","2, 3, 6, 18, 108, ?",["648","216","1944","1296"],2,"Each term is the product of the two before it: 18 x 108."],["pa","h","1, 4, 13, 40, ?",["120","160","81","121"],3,"Multiply by 3 and add 1."],["pa","h","C, F, J, O, ?",["U","T","V","S"],0,"The gaps grow by one: +3, +4, +5, +6."],["pa","h","0, 3, 8, 15, 24, ?",["33","35","36","48"],1,"Each term is one less than a square: 36 - 1."],["pa","h","J, F, M, A, M, J, ?",["A","S","J","D"],2,"First letters of the months: the next is July."],["pa","h","5, 6, 9, 14, 21, ?",["28","29","32","30"],3,"The differences are odd numbers: 1, 3, 5, 7, 9."],["gr","e","Fill in: She ___ to the market every Sunday.",["goes","go","going","gone"],0,"Third person singular in the simple present takes 'goes'."],["gr","e","Fill in: Rahul and ___ finished the report.",["me","I","myself","mine"],1,"'I' is the subject form."],["gr","e","The plural of 'box' is...",["boxs","boxen","boxes","boxies"],2,"Nouns ending in -x add -es."],["gr","e","Fill in with the correct article: She ate ___ orange.",["an","a","no article"],0,"'An' is used before a vowel sound."],["gr","e","Choose the correct spelling.",["Receive","Recieve","Receeve","Riceive"],0,"'I before e except after c' - receive."],["gr","e","Fill in: Please call me ___ you reach the office.",["what","when","which","who"],1,"'When' introduces a time clause."],["gr","m","Fill in: Neither the manager nor the clerks ___ aware of the change.",["was","is","were","has"],2,"With neither/nor the verb agrees with the nearer subject, 'clerks'."],["gr","m","Choose the correct sentence.",["Each of the boxes have a label.","Each of the boxes having a label.","Each of the boxes are having a label.","Each of the boxes has a label."],3,"'Each' is singular and takes 'has'."],["gr","m","Fill in: By the time we arrived, the train ___.",["had left","has left","leaves","will leave"],0,"The past perfect shows the earlier of two past actions."],["gr","m","Fill in: I look forward to ___ from you.",["hear","hearing","heard","be hearing"],1,"'Look forward to' is followed by the -ing form."],["gr","m","Find the error: 'She don't like waiting in long queues.'",["'like' should be 'likes'","'waiting' should be 'wait'","'don't' should be 'doesn't'","'long' should be 'longer'"],2,"'She' takes 'doesn't'."],["gr","m","Fill in: The new policy will ___ all employees.",["effect","effecting","affection","affect"],3,"'Affect' is the verb meaning to have an influence on."],["gr","h","Choose the correct sentence.",["Had I known, I would have helped.","Had I knew, I would have helped.","If I would have known, I helped.","Had I known, I will help."],0,"Third conditional: had + past participle, would have + past participle."],["gr","h","Fill in: It is high time we ___ the issue.",["resolve","resolved","will resolve","are resolving"],1,"'It is high time' is followed by the past tense."],["gr","h","Which sentence has correct parallel structure?",["She likes reading, to write and painting.","She likes to read, writing and paint.","She likes reading, writing and painting.","She likes read, writing and to paint."],2,"All three items use the same -ing form."],["gr","h","Fill in: ___ did you send the invoice to?",["Whose","Who's","Whomever","Whom"],3,"The object of 'to' takes 'whom'."],["gr","h","Find the error: 'Each of the candidates have submitted the form on time.'",["'have' should be 'has'","'candidates' should be 'candidate'","'submitted' should be 'submit'","'on time' should be 'in time'"],0,"'Each' is singular, so 'has'."],["gr","h","Choose the correctly punctuated sentence.",["The report which was due on Monday, arrived late.","The report, which was due on Monday, arrived late.","The report, which was due on Monday arrived late.","The report which, was due on Monday arrived late."],1,"A non-defining clause is enclosed by a pair of commas."],["vo","e","Which word is closest in meaning to 'begin'?",["Finish","Wait","Start","Stop"],2,"To begin is to start."],["vo","e","Which word is the opposite of 'generous'?",["Kind","Wealthy","Gentle","Stingy"],3,"Generous means giving freely; stingy means unwilling to give."],["vo","e","Which word is closest in meaning to 'quick'?",["Fast","Slow","Heavy","Quiet"],0,"Quick means fast."],["vo","e","Which word is the opposite of 'ancient'?",["Old","Modern","Broken","Large"],1,"Ancient means very old; modern means new."],["vo","e","Which word means 'very happy'?",["Tired","Anxious","Delighted","Bored"],2,"Delighted means very pleased."],["vo","e","Which word is the opposite of 'accept'?",["Receive","Agree","Allow","Reject"],3,"To reject is to refuse to accept."],["vo","m","Which word is closest in meaning to 'reluctant'?",["Unwilling","Eager","Careless","Honest"],0,"Reluctant means unwilling."],["vo","m","Which word is the opposite of 'expand'?",["Enlarge","Contract","Extend","Increase"],1,"To contract is to become smaller."],["vo","m","What does 'meticulous' mean?",["Very fast","Easily angered","Very careful about details","Rarely seen"],2,"A meticulous person pays close attention to detail."],["vo","m","Fill in: The manager gave such a ___ answer that nobody understood what she meant.",["precise","clear","detailed","vague"],3,"Vague means unclear."],["vo","m","Which word is closest in meaning to 'abundant'?",["Plentiful","Scarce","Hidden","Tiny"],0,"Abundant means existing in large amounts."],["vo","m","What does 'to hit the nail on the head' mean?",["To make a serious mistake","To describe exactly what is causing a problem","To work with tools","To lose one's temper"],1,"The idiom means to be exactly right."],["vo","h","Which word is closest in meaning to 'ephemeral'?",["Everlasting","Colourful","Short-lived","Enormous"],2,"Ephemeral means lasting a very short time."],["vo","h","Which word is the opposite of 'candid'?",["Frank","Honest","Cheerful","Evasive"],3,"Candid means open and direct; evasive means avoiding direct answers."],["vo","h","What does 'pragmatic' mean?",["Dealing with things in a practical way","Extremely emotional","Fond of arguing","Careless about rules"],0,"Pragmatic means practical and realistic."],["vo","h","Fill in: Her ___ remarks offended everyone in the meeting.",["diplomatic","tactless","tactful","considerate"],1,"Tactless remarks are thoughtless and can offend."],["vo","h","Which word is closest in meaning to 'obsolete'?",["Popular","Essential","Outdated","Durable"],2,"Obsolete means no longer in use."],["vo","h","What does 'to procrastinate' mean?",["To plan carefully ahead","To speak in public","To work very quickly","To keep delaying something that should be done"],3,"Procrastinating is putting things off."],["pr","e","A pen costs Rs 15. How much do 6 pens cost?",["Rs 90","Rs 80","Rs 75","Rs 105"],0,"6 x 15 = 90."],["pr","e","You have Rs 500 and spend Rs 175. How much is left?",["Rs 335","Rs 325","Rs 275","Rs 375"],1,"500 - 175 = 325."],["pr","e","A shop opens at 9:30 am and closes at 6:00 pm. How long is it open?",["8 hours","9 hours 30 minutes","8 hours 30 minutes","7 hours 30 minutes"],2,"9:30 to 5:30 is 8 hours, plus 30 minutes."],["pr","e","Four people share 120 boxes equally. How many boxes does each person pack?",["40","24","25","30"],3,"120 / 4 = 30."],["pr","e","What is 10% of 850?",["85","8.5","850","95"],0,"10% is one tenth: 85."],["pr","e","A train leaves at 2:45 pm and the journey takes 50 minutes. When does it arrive?",["3:25 pm","3:35 pm","3:45 pm","3:15 pm"],1,"2:45 + 15 minutes = 3:00, then 35 more minutes."],["pr","m","An item priced Rs 1,200 is sold at a 15% discount. What is the selling price?",["Rs 1,050","Rs 1,180","Rs 1,020","Rs 1,000"],2,"15% of 1,200 is 180; 1,200 - 180 = 1,020."],["pr","m","A car travels 180 km in 3 hours. At the same speed, how far does it go in 5 hours?",["280 km","320 km","250 km","300 km"],3,"60 km per hour x 5 = 300 km."],["pr","m","Three tasks take 25, 40 and 35 minutes. You start at 2:10 pm and do them one after another. When do you finish?",["3:50 pm","3:40 pm","4:00 pm","3:35 pm"],0,"100 minutes after 2:10 pm is 3:50 pm."],["pr","m","A price rises from Rs 400 to Rs 460. What is the percentage increase?",["60%","15%","13%","12%"],1,"60 / 400 = 15%."],["pr","m","Out of 80 forms, 15% have errors. How many forms have no errors?",["12","65","68","72"],2,"15% of 80 is 12; 80 - 12 = 68."],["pr","m","A customer reports a problem you cannot fix yourself. What is the best next step?",["Tell the customer it is not your job","Wait until the customer calls again","Promise a fix by tonight without checking","Note the details, pass it to the right person and tell the customer what happens next"],3,"Recording, routing and keeping the customer informed solves the problem without false promises."],["pr","h","One worker finishes a job in 6 hours and another in 3 hours. Working together, how long do they take?",["2 hours","4.5 hours","3 hours","1.5 hours"],0,"Together they do 1/6 + 1/3 = 1/2 of the job per hour."],["pr","h","A price is increased by 20% and then reduced by 20%. Compared with the original, the final price is...",["The same","4% lower","4% higher","2% lower"],1,"1.2 x 0.8 = 0.96."],["pr","h","Rs 12,000 is shared between A and B in the ratio 3:5. How much does B get?",["Rs 4,500","Rs 7,200","Rs 7,500","Rs 8,000"],2,"5/8 of 12,000 = 7,500."],["pr","h","A queue of 45 requests is cleared at 9 per hour, but 3 new requests arrive every hour. How many hours until the queue is empty?",["5 hours","4 hours","6 hours","7.5 hours"],3,"The queue shrinks by 6 an hour: 45 / 6 = 7.5."],["pr","h","Rs 5,000 earns 8% simple interest per year. What is the total after 3 years?",["Rs 6,200","Rs 6,298.56","Rs 5,400","Rs 6,000"],0,"Interest is 400 a year, 1,200 in 3 years."],["pr","h","Two reports disagree: one says 1,250 orders, the other 1,205. What is the most sensible first step?",["Use the larger number","Check both against the original source to find which is wrong","Average the two figures","Report both and let others decide"],1,"A mismatch is resolved by going back to the source record."]]$J$::jsonb) LOOP
 SELECT jsonb_agg(jsonb_build_object('id',chr(97+(ord-1)::int),'text',t) ORDER BY ord) INTO o FROM jsonb_array_elements_text(r->3) WITH ORDINALITY x(t,ord);
 PERFORM public.cbt_save_question(NULL, jsonb_build_object('type','mcq','pool','hiring','subject',CASE r->>0 WHEN 'lo' THEN 'logical_reasoning' WHEN 'pa' THEN 'pattern_recognition' WHEN 'gr' THEN 'grammar' WHEN 'vo' THEN 'vocabulary' ELSE 'problem_solving' END,
  'difficulty',CASE r->>1 WHEN 'e' THEN 'easy' WHEN 'm' THEN 'medium' ELSE 'hard' END,'status','needs_review',
  'content',jsonb_build_object('prompt',r->>2,'options',o),'key',jsonb_build_object('correct_option_id',chr(97+(r->>4)::int),'explanation',r->>5)));
END LOOP; END $D$;
SELECT public.cbt_save_question(NULL, $J${"type": "typing_passage", "pool": "shared", "subject": "typing_passages", "difficulty": "easy", "status": "needs_review", "content": {"passage": "The morning bus was late again, so Meera decided to walk to work. The air was cool and the streets were quiet. She passed a small tea stall where an old man was reading the news. A few children waited at the corner with their school bags. Meera liked walking because it gave her time to think about the day ahead. She made a list in her mind of the tasks she had to finish. First she would reply to her emails, then she would call two clients, and after lunch she would check the weekly report. By the time she reached the office, she felt calm and ready to begin.", "level": "beginner"}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "typing_passage", "pool": "shared", "subject": "typing_passages", "difficulty": "easy", "status": "needs_review", "content": {"passage": "A good habit is easy to start but hard to keep. Many people decide to read more, sleep early or drink more water. For a few days they do well, and then old habits return. One simple way to keep a new habit is to make it small. Read one page a day instead of one chapter. Walk for ten minutes instead of one hour. When the habit becomes part of your day, you can slowly make it bigger. It also helps to link the new habit to something you already do, such as reading a page after dinner every night. Small steps, repeated each day, lead to big changes over time.", "level": "beginner"}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "typing_passage", "pool": "shared", "subject": "typing_passages", "difficulty": "medium", "status": "needs_review", "content": {"passage": "Public libraries have changed a great deal over the last few decades. They were once quiet buildings filled with shelves of books, where visitors spoke in whispers and borrowed a novel for two weeks. Today, many libraries offer free internet access, study rooms, language classes and workshops for children. Some even lend tools, musical instruments and board games. Librarians still help people find books, but they also teach visitors how to search online, fill in forms and spot information that is not reliable. For students who do not have a quiet place at home, the library is often the best place to study. For older people, it can be a place to meet others and learn new skills. Although more people now read on phones and tablets, libraries remain popular because they are open to everyone and cost nothing to use. In many towns, the library is one of the few places where people of every age and background spend time under the same roof.", "level": "intermediate"}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "typing_passage", "pool": "shared", "subject": "typing_passages", "difficulty": "medium", "status": "needs_review", "content": {"passage": "Working well in a team is a skill that can be learned. It starts with listening carefully, so that you understand what others need before you offer your own view. Good team members share information early, especially when something is going wrong, because a small problem reported in the morning is much easier to fix than a large one discovered at the end of the day. They keep their promises, and when they cannot, they say so honestly and suggest another plan. They also give credit to others and avoid blaming people in front of the group. Disagreements are normal in any team, and they can even lead to better ideas, as long as people argue about the work and not about each other. Finally, a strong team celebrates its successes, however small, and takes time to learn from its mistakes. Over time, these simple habits build trust, and trust allows a team to move faster and achieve more than any one person could alone.", "level": "intermediate"}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "typing_passage", "pool": "shared", "subject": "typing_passages", "difficulty": "hard", "status": "needs_review", "content": {"passage": "The first postage stamp, known as the Penny Black, was issued in Britain on 1 May 1840; before then, the person receiving a letter usually paid for it, and the price depended on the distance travelled and the number of sheets used. Reformers argued that a single, low, prepaid rate would encourage people to write more often, and they were right: within a few years, the number of letters sent each year had more than doubled. Other countries soon followed, and by the 1860s stamps were in use across Europe, the Americas and parts of Asia. Postal systems also had to solve practical problems. How should addresses be written? Who would carry mail across borders, and at what cost? In 1874, twenty-two countries met in Bern, Switzerland, and agreed to form what became the Universal Postal Union, which still sets common rules today. Although e-mail and messaging apps have replaced many letters, parcels are now more important than ever; in 2023, postal services around the world handled billions of items, many of them ordered online and delivered within 24 to 48 hours.", "level": "advanced"}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "typing_passage", "pool": "shared", "subject": "typing_passages", "difficulty": "hard", "status": "needs_review", "content": {"passage": "Weather forecasting has improved remarkably since the middle of the twentieth century. Early forecasters relied on a handful of observations - temperature, air pressure, wind direction and cloud cover - collected at weather stations and sent by telegraph. Today, satellites, radar, ocean buoys and thousands of automatic stations send data every few minutes, and powerful computers use this information to solve the equations that describe how the atmosphere moves. A five-day forecast is now roughly as accurate as a one-day forecast was in the 1980s. Even so, forecasts are never certain. The atmosphere is a chaotic system, which means that a tiny error in the starting data can grow into a large error after a week or two. To deal with this, forecasters run the same model many times with slightly different starting conditions; if most runs agree, confidence is high, and if they disagree, the forecast is given as a range of possibilities. This is why a forecast might say there is a 70% chance of rain, rather than simply promising that it will (or will not) rain tomorrow.", "level": "advanced"}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "written", "pool": "hiring", "subject": "written_communication", "difficulty": "medium", "status": "needs_review", "content": {"prompt": "A customer writes: \"I was told my refund would reach my account in two days. It has been five days and nothing has arrived.\" Write a polite reply to the customer.", "min_words": 60, "max_words": 150}, "key": {"rubric": {"covers": ["Apologises for the delay and acknowledges the customer's frustration", "Explains what will be checked or done next", "Gives a realistic time for the next update", "Asks only for details needed to trace the refund (such as a reference number)", "Ends politely and professionally"], "must_not": ["Blames the customer", "Promises an exact date that cannot be guaranteed", "Asks for a password, PIN or OTP", "Rude or sarcastic language"], "max_marks": 20}}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "written", "pool": "hiring", "subject": "written_communication", "difficulty": "medium", "status": "needs_review", "content": {"prompt": "A client asks you to waive a service fee because they have been a customer for many years. Company policy does not allow fee waivers. Write a polite message declining the request.", "min_words": 60, "max_words": 150}, "key": {"rubric": {"covers": ["Thanks the client for their loyalty", "Says clearly that the fee cannot be waived", "Briefly explains that the policy applies to all clients", "Offers an alternative or further help where possible", "Keeps a warm and respectful tone"], "must_not": ["Gives false hope that the fee may be waived later", "Criticises the policy or the company", "Rude or dismissive language"], "max_marks": 20}}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "written", "pool": "hiring", "subject": "written_communication", "difficulty": "medium", "status": "needs_review", "content": {"prompt": "A week ago you emailed a client asking them to confirm their new address, but they have not replied. Write a short follow-up message.", "min_words": 40, "max_words": 120}, "key": {"rubric": {"covers": ["Refers to the earlier message and its purpose", "Restates clearly what is needed from the client", "Gives a reason or a reasonable deadline", "Makes it easy to reply", "Stays polite without pressuring the client"], "must_not": ["Accusing or impatient tone", "Threats or warnings of penalties", "Unrelated personal information"], "max_marks": 20}}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "written", "pool": "hiring", "subject": "written_communication", "difficulty": "medium", "status": "needs_review", "content": {"prompt": "A new colleague asks how to reset their password on a company website. The sign-in page has a \"Forgot password\" link, and the site emails a reset link. Explain the process in numbered steps.", "min_words": 60, "max_words": 180}, "key": {"rubric": {"covers": ["Uses numbered steps in a logical order", "Mentions the Forgot password link on the sign-in page", "Says to open the reset email and its link (and to check the spam folder)", "Advises choosing a new, strong password", "Says to sign in with the new password and whom to contact if it fails"], "must_not": ["Asks the colleague to share their password with anyone", "Suggests a weak or shared password"], "max_marks": 20}}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "written", "pool": "hiring", "subject": "written_communication", "difficulty": "medium", "status": "needs_review", "content": {"prompt": "You sent a client an invoice for Rs 12,500 instead of Rs 2,500. The client noticed and wrote to you. Write a reply that apologises and puts it right.", "min_words": 60, "max_words": 150}, "key": {"rubric": {"covers": ["Apologises sincerely and takes responsibility", "States the correct amount clearly", "Says a corrected invoice is attached or when it will be sent", "Explains how the mistake will be avoided in future", "Thanks the client for pointing it out"], "must_not": ["Blames a colleague or the system without taking responsibility", "Asks the client to pay the wrong amount", "Overly casual language"], "max_marks": 20}}}$J$::jsonb);
SELECT public.cbt_save_question(NULL, $J${"type": "written", "pool": "hiring", "subject": "written_communication", "difficulty": "medium", "status": "needs_review", "content": {"prompt": "Your team lead was on leave today. During the day the office internet was down from 10:00 to 11:30, two customer complaints about late deliveries were received and passed to the delivery team, and a new team member joined and completed induction. Write a short summary for your team lead.", "min_words": 50, "max_words": 130}, "key": {"rubric": {"covers": ["Mentions the internet outage and its timing", "Mentions the two complaints and that they went to the delivery team", "Mentions the new team member and the completed induction", "Uses a clear structure (short paragraphs or bullet points)", "Notes any follow-up the team lead may need to do"], "must_not": ["Events that are not in the scenario", "Personal opinions about colleagues"], "max_marks": 20}}}$J$::jsonb);
